function [CRI2012Ra,DERMS]=CRI2012_c(spd,sampleset,thetas,scalingpars)
if nargin<3;thetas=[0 360];scalinpars=[];end
if nargin<4;scalinpars=[];end

%set default scaling parameters
if isempty(scalingpars)
    switch sampleset
        case 17
            scalingpars=1/55;%mean(CRI2012 Ra(F1-F12))=mean(CIE Ra(F1-F12)))
        case 210
            scalingpars=2/45;%mean(CRI2012 Ra(F1-F12))=mean(CIE Ra(F1-F12)))
        case 1000
            scalingpars=1/50;%mean(CRI2012 Ra(F1-F12))=mean(CIE Ra(F1-F12)))
    end
end

%run regular code
[~,~,DERMS,DEi,aMc,bMc,Jc,XYZ,cct,duv,aMr,bMr,Jr,rflset]=CRI2012_sub(spd,scalingpars,[0, 360],sampleset);%CRI2012 (HL17)

%--------------------------------------------------------------------------

%correct metric calculation for possible missing samples
[usesamples,Nsamples]=selectsampleswithinhueintervalthetas(thetas,rflset,10);%select samples within hue interval

%calculate new average index/DE
DERMS=sqrt(sum(DEi(usesamples).^2)./length(DEi(usesamples)));

% Apply Rescaling
if sum(usesamples)==Nsamples
    %keep regular rescaling parameters
    switch sampleset
        case 17
            rescaling_pars=1/55;%mean(CRI2012 Ra(F1-F12))=mean(CIE Ra(F1-F12)))
        case 210
            rescaling_pars=2/45;%mean(CRI2012 Ra(F1-F12))=mean(CIE Ra(F1-F12)))
        case 1000
            rescaling_pars=1/50;%mean(CRI2012 Ra(F1-F12))=mean(CIE Ra(F1-F12)))
    end
else
    %use new for particular subset of samples
    rescaling_pars=scalingpars;
end

%apply rescaling
CRI2012Ra = 100 * (2 ./ (exp((rescaling_pars) .* abs(DERMS) .^ (3 / 2)) + 1)) .^ 2;

end

